node -e "
const now = new Date();
const year = now.getFullYear();
const sep1 = new Date(year, 8, 1); // September is month index 8
const dayOfWeek = sep1.getDay(); // 0=Sun, 1=Mon, ...
const daysUntilMonday = dayOfWeek <= 1 ? (1 - dayOfWeek) : (8 - dayOfWeek);
const laborDay = new Date(year, 8, 1 + daysUntilMonday);
console.log('Labor Day ' + year + ': ' + laborDay.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
"

